def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)
    def rand_ops(n, lo, hi, push_p):
        ops, size = [], 0
        for _ in range(n):
            if size == 0 or rng.random() < push_p:
                ops.append('push ' + str(rng.randint(lo, hi)))
                size += 1
            else:
                o = rng.choice(['pop', 'top', 'getmin', 'getmin'])
                ops.append(o)
                if o == 'pop':
                    size -= 1
        return ops
    tests = [
        fmt(['push 1', 'top', 'getmin']),
        fmt(['push 5', 'push 5', 'push 5', 'pop', 'getmin', 'pop', 'getmin']),
        fmt(['push 1000000000', 'push -1000000000', 'getmin', 'top', 'pop', 'getmin', 'top']),
        fmt(['push 3', 'push 2', 'push 1', 'getmin', 'pop', 'getmin', 'pop', 'getmin']),
        fmt(['push 1', 'push 2', 'push 3', 'getmin', 'pop', 'getmin', 'pop', 'getmin']),
    ]
    for n, lo, hi, pp in ((8, -3, 3, 0.6), (12, 0, 4, 0.6), (16, -5, 5, 0.5), (20, 1, 3, 0.5), (24, -10, 10, 0.55), (30, 0, 2, 0.5), (35, -4, 4, 0.5), (40, -20, 20, 0.45)):
