    N = 40000
    tests.append(fmt(rand_ops(N, -10**9, 10**9, 0.55)))
    tests.append(fmt(rand_ops(N, -3, 3, 0.52)))
    tests.append(fmt(['push ' + str(rng.randint(-10**9, 10**9)) for _ in range(N // 2)] + ['getmin', 'pop'] * (N // 4)))
